use vstd::prelude::*;

verus! {
    // Helper function to convert a character to lowercase if it's an uppercase ASCII letter
    spec fn to_lower(c: char) -> char {
        if c >= 'A' && c <= 'Z' {
            (c as u8 + 32) as char // Convert to lowercase
        } else {
            c // Return unchanged
        }
    }

    // Main function to check if the array forms a palindrome
    fn is_palindrome(text: Vec<char>) -> (result: bool)
        ensures
            result == (forall |i: nat| (i < text.len() as nat) ==> 
                to_lower(text[i as usize]) == to_lower(text[(text.len() - 1 - i as usize) as usize])),
    {
        let n = text.len() as nat;
        let mut i: nat = 0;

        // Loop to check characters from both ends towards the center
        while i < n / 2
            invariant
                i <= n / 2,
                forall |j: nat| (j < i ==> 
                    to_lower(text[j as usize]) == to_lower(text[(n - 1 - j as usize)])),
            decreases n / 2 - i,
        {
            // Check the characters at mirrored positions
            assert(to_lower(text[i as usize]) == to_lower(text[(n - 1 - i as usize)]));
            i = i + 1;
        }

        // If we reach here, all mirrored characters matched
        true
    }
}
